import{_ as a}from"./chunks/ark_dist.BU6IWzVh.js";import{_ as r,o,c as n,al as i}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"ARK DIST SR","description":"","frontmatter":{},"headers":[],"relativePath":"ko/dronecan/ark_dist.md","filePath":"ko/dronecan/ark_dist.md"}'),t={name:"ko/dronecan/ark_dist.md"};function l(c,e,d,s,h,f){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="ark-dist-sr" tabindex="-1">ARK DIST SR <a class="header-anchor" href="#ark-dist-sr" aria-label="Permalink to &quot;ARK DIST SR&quot;">​</a></h1><p>ARK DIST SR is a low range, open source <a href="./">DroneCAN</a> <a href="./../sensor/rangefinders">distance sensor</a>. It has an approximate range of between 8cm to 30m.</p><p><img src="'+a+'" alt="ARK DIST SR"></p><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><p>Order this module from:</p><ul><li><a href="https://arkelectron.com/product/ark-dist-sr/" target="_blank" rel="noreferrer">ARK Electronics</a> (US)</li></ul><h2 id="hardware-specifications" tabindex="-1">Hardware Specifications <a class="header-anchor" href="#hardware-specifications" aria-label="Permalink to &quot;Hardware Specifications&quot;">​</a></h2><ul><li><a href="https://github.com/ARK-Electronics/ARK_DIST" target="_blank" rel="noreferrer">Open Source Schematic and BOM</a></li><li>센서 <ul><li><a href="https://www.broadcom.com/products/optical-sensors/time-of-flight-3d-sensors/afbr-s50lv85d" target="_blank" rel="noreferrer">Broadcom AFBR-S50LV85D Time-of-Flight Distance Sensor</a><ul><li>Typical distance range up to 30m</li><li>Integrated 850 nm laser light source</li><li>Field-of-View (FoV) of 12.4° x 6.2° with 32 pixels</li><li>Operation of up to 200k Lux ambient light</li><li>Reference Pixel for system health monitoring</li><li>Works well on all surface conditions</li><li>Transmitter beam of 2° x 2° to illuminate between 1 and 3 pixels</li></ul></li></ul></li><li>Two Pixhawk Standard CAN Connectors (4 Pin JST GH)</li><li>Pixhawk Standard UART Connector (6 Pin JST SH)</li><li>Pixhawk Standard Debug Connector (6 Pin JST SH)</li><li>Small Form Factor <ul><li>2.0cm x 2.8cm x 1.4cm</li><li>4g</li></ul></li><li>LED Indicators</li><li>USA Built</li><li>NDAA Compliant</li><li>Power Requirements <ul><li>5v <ul><li>84mA Average</li><li>86mA Max</li></ul></li></ul></li></ul><h2 id="하드웨어-설정" tabindex="-1">하드웨어 설정 <a class="header-anchor" href="#하드웨어-설정" aria-label="Permalink to &quot;하드웨어 설정&quot;">​</a></h2><h3 id="배선" tabindex="-1">배선 <a class="header-anchor" href="#배선" aria-label="Permalink to &quot;배선&quot;">​</a></h3><p>The ARK DIST is connected to the CAN bus using a Pixhawk standard 4 pin JST GH cable. For more information, refer to the <a href="./../can/#wiring">CAN Wiring</a> instructions.</p><p>The ARK DIST can also be connected with UART and communicates over MAVLink sending the <a href="https://mavlink.io/en/messages/common.html#DISTANCE_SENSOR" target="_blank" rel="noreferrer">DISTANCE_SENSOR</a> message.</p><h2 id="firmware-setup" tabindex="-1">Firmware Setup <a class="header-anchor" href="#firmware-setup" aria-label="Permalink to &quot;Firmware Setup&quot;">​</a></h2><p>ARK DIST SR runs the <a href="./px4_cannode_fw">PX4 DroneCAN Firmware</a>. As such, it supports firmware update over the CAN bus and <a href="./#node-id-allocation">dynamic node allocation</a>.</p><h2 id="px4-설정" tabindex="-1">PX4 설정 <a class="header-anchor" href="#px4-설정" aria-label="Permalink to &quot;PX4 설정&quot;">​</a></h2><h3 id="dronecan" tabindex="-1">DroneCAN <a class="header-anchor" href="#dronecan" aria-label="Permalink to &quot;DroneCAN&quot;">​</a></h3><h4 id="enable-dronecan" tabindex="-1">Enable DroneCAN <a class="header-anchor" href="#enable-dronecan" aria-label="Permalink to &quot;Enable DroneCAN&quot;">​</a></h4><p>단계는 다음과 같습니다:</p><ul><li>In <em>QGroundControl</em> set the parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> for dynamic node allocation (or <code>3</code> if using <a href="./../dronecan/escs">DroneCAN ESCs</a>) and reboot (see <a href="./../advanced_config/parameters">Finding/Updating Parameters</a>).</li><li>Connect ARK DIST SR CAN to the Pixhawk CAN.</li></ul><p>Once enabled, the module will be detected on boot. Distance sensor data should arrive at 40Hz.</p><p>DroneCAN configuration in PX4 is explained in more detail in <a href="./../dronecan/#enabling-dronecan">DroneCAN &gt; Enabling DroneCAN</a>.</p><h4 id="can-configuration" tabindex="-1">CAN Configuration <a class="header-anchor" href="#can-configuration" aria-label="Permalink to &quot;CAN Configuration&quot;">​</a></h4><p>First set the parameters to <a href="#enable-dronecan">Enable DroneCAN</a> (as shown above).</p><p>Set the following parameters in <em>QGroundControl</em>:</p><ul><li>Enable <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to 2 for dynamic node allocation.</li><li>Enable <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_RNG">UAVCAN_SUB_RNG</a>.</li><li>Set <a href="./../advanced_config/parameter_reference#EKF2_RNG_A_HMAX">EKF2_RNG_A_HMAX</a> to <code>30</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#EKF2_RNG_QLTY_T">EKF2_RNG_QLTY_T</a> to <code>0.2</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#UAVCAN_RNG_MIN">UAVCAN_RNG_MIN</a> to <code>0.08</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#UAVCAN_RNG_MAX">UAVCAN_RNG_MAX</a> to <code>30</code>.</li></ul><p>See also <a href="./../dronecan/#distance-sensor-range-finder">Distance Sensor/Range Finder in <em>DroneCAN &gt; Subscriptions and Publications</em></a>.</p><h3 id="uart-mavlink-configuration" tabindex="-1">UART/MAVLink Configuration <a class="header-anchor" href="#uart-mavlink-configuration" aria-label="Permalink to &quot;UART/MAVLink Configuration&quot;">​</a></h3><p>If connecting via a UART set the following parameters in <em>QGroundControl</em>:</p><ul><li>Set <a href="./../advanced_config/parameter_reference#MAV_0_CONFIG">MAV_X_CONFIG</a> to the port the sensor is connected to.</li><li>Set <a href="./../advanced_config/parameter_reference#MAV_0_FORWARD">MAV_X_FORWARD</a> to <code>0</code> (off).</li><li>Set <a href="./../advanced_config/parameter_reference#MAV_0_MODE">MAV_X_MODE</a> to <code>7</code> or <code>13</code> to (Minimal or Low Bandwidth) to reduce memory usage.</li><li>Set <code>SER_XXX_BAUD</code> to <code>115200</code>, where <code>XXX</code> is specific to the port you are using (such as <a href="./../advanced_config/parameter_reference#SER_GPS2_BAUD">SER_GPS2_BAUD</a>).</li><li>Set <a href="./../advanced_config/parameter_reference#EKF2_RNG_A_HMAX">EKF2_RNG_A_HMAX</a> to <code>30</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#EKF2_RNG_QLTY_T">EKF2_RNG_QLTY_T</a> to <code>0.2</code>.</li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="https://docs.arkelectron.com/sensor/ark-dist" target="_blank" rel="noreferrer">ARK DIST SR</a> (ARK Docs)</li></ul>',31)])])}const A=r(t,[["render",l]]);export{u as __pageData,A as default};
